// The front side: the astronaut's own screen. Idea, structure and logic: the human member of team
// "Just For Fun" (one dated message about body and mind, a short explanation, buttons, a choice; tell only
// when something is really wrong). Inspired by NASA's rules for crew screens (NASA-STD-3001 Vol 2 Rev F):
// a status bar that is always visible, colour that carries meaning, a list of alerts with what to do.
// Code generated by Claude (Anthropic), an AI system; the variants and thresholds are Claude's drafts.
import { createMachine, STATUS, KIND } from './engine.js';
import { CELLS, SOURCES, CREW, SHIP, realPeople } from './config.js';
import { cycleSummary, lowDaysByPhase, CYCLE_RULES } from './cycle.js';
import { INSPIRATION4 } from './inspiration4.js';
import { openStore } from './store.js';
import { exampleFlight, MISSION } from './demo-crew.js';
import { drawHistory, drawTable, fmtDate, fmtGMT } from './history-view.js';
import { assess, assessShip, measureState, headline, LEVEL, LEVEL_WORD, EXPECTED, RULES as LEVEL_RULES } from './state-levels.js';
import { RULES as CAM_RULES } from './camera-rules.js';
import { icon } from './icons.js';
import { initTips, tipButton, hideTip } from './explain.js';
import { TIPS, PROVENANCE } from './tips.js';

// One icon per measure, so a list can be read at a glance.
const ICON_FOR = { pulse: 'heart-pulse', bp: 'activity', glucose: 'droplet', temp: 'thermometer', spo2: 'droplets', sleep: 'moon', resp: 'wind', fluid: 'glass-water', bodyMass: 'scale', eyePressure: 'eye', hearing: 'ear', radiation: 'radiation', vo2max: 'heart', strength: 'dumbbell', bone: 'bone', camera: 'camera', mood: 'smile', attitude: 'battery', sleepQuality: 'bed', cognition: 'brain', cycle: 'calendar-heart', xray: 'scan-line', ecg: 'chart-line', ultrasound: 'waves', co2: 'cloud-fog', cabinTemp: 'thermometer', cabinO2: 'orbit', cabinPressure: 'gauge', noise: 'volume-2', blood: 'test-tube' };
const NAV = [['home', 'Today', 'house'], ['measures', 'All measures', 'list'], ['alerts', 'Messages', 'bell'], ['setup', 'Settings', 'settings']];

const DAY = 24 * 60 * 60 * 1000;
const REAL = realPeople(INSPIRATION4.subjects);
const PEOPLE = [...CREW, SHIP, ...REAL];
const personById = Object.fromEntries(PEOPLE.map((p) => [p.id, p]));
const cellBy = Object.fromEntries(CELLS.map((c) => [c.indicator, c]));
const sourceFor = (indicator) => SOURCES.find((s) => s.indicator === indicator);

// ---------- small helpers ----------
const byId = (id) => document.getElementById(id);
function h(tag, props = {}, ...children) {
  const node = document.createElement(tag);
  for (const [k, v] of Object.entries(props || {})) {
    if (v === undefined || v === null || v === false) continue;
    if (k === 'class') node.className = v;
    else if (k === 'text') node.textContent = v;
    else if (k === 'dataset') Object.assign(node.dataset, v);
    else if (k.startsWith('on') && typeof v === 'function') node.addEventListener(k.slice(2), v);
    else node.setAttribute(k, v === true ? '' : String(v));
  }
  for (const c of children.flat()) {
    if (c === null || c === undefined || c === false) continue;
    node.append(c instanceof Node ? c : document.createTextNode(String(c)));
  }
  return node;
}
// replaceChildren would print null as text; fill() leaves out empty parts.
const fill = (host, ...kids) => host.replaceChildren(...kids.flat().filter((k) => k !== null && k !== undefined && k !== false));
const two = (n) => String(n).padStart(2, '0');
const fmtVal = (v) => (Number.isFinite(Number(v)) ? String(Math.round(Number(v) * 10) / 10) : String(v));
const fmtDT = (t) => fmtGMT(t);
// GMT day of the year, as on the ISS: "GMT 318/18:00".
const doy = (d) => Math.floor((Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()) - Date.UTC(d.getUTCFullYear(), 0, 0)) / DAY);
const gmtDOY = (t) => { const d = new Date(t); return `${doy(d)}/${two(d.getUTCHours())}:${two(d.getUTCMinutes())}`; };
const cap = (s) => (s ? s.charAt(0).toUpperCase() + s.slice(1) : s);
const ageText = (t, now) => { const hrs = (msOf(now) - msOf(t)) / 3.6e6; return hrs >= 48 ? `${Math.floor(hrs / 24)} days` : `${Math.max(1, Math.round(hrs))} h`; };
const lower = (s) => s.charAt(0).toLowerCase() + s.slice(1);
const msOf = (t) => (t instanceof Date ? t.getTime() : new Date(t).getTime());
const LV_CLASS = ['lv0', 'lv1', 'lv2', 'lv3'];

function toast(text) {
  const node = h('div', { class: 'toast', role: 'status' }, text);
  document.body.append(node);
  setTimeout(() => node.remove(), 3600);
}

// Per-device conveniences only (the switches of the situation, the muted sound, seen alerts).
const KEY = 'jff-crew-ui-v1';
function loadPrefs() {
  try { return JSON.parse(localStorage.getItem(KEY) || '{}'); } catch { return {}; }
}
function savePrefs() {
  try { localStorage.setItem(KEY, JSON.stringify({ ship: ui.ship, muted: ui.muted, seen: [...ui.seen], example: ui.example, profile: ui.profile })); } catch { /* storage blocked: the page still works */ }
}

// ---------- state ----------
const prefs = loadPrefs();
const ui = {
  person: null,
  screen: 'home',
  detail: null, // indicator, or 'blood:<analyte code>'
  period: 'flight',
  from: '',
  to: '',
  ship: { aiWorks: true, doctorOnBoard: false, linkToEarth: true, ...(prefs.ship || {}) },
  muted: Boolean(prefs.muted),
  example: prefs.example !== false,
  seen: new Set(prefs.seen || []),
  checkin: { mood: null, attitude: null, sleepQuality: null },
  checkinOpen: false,
  find: '',
  backTo: 'measures',
  stepsDone: {},
  openGroups: new Set(),
  profile: prefs.profile || 'iss',
};
let store = null;
let stored = [];
let machine = null;
let camStop = null;

// The time the screen lives in: with the example flight on, the example's "today" or later saved readings.
function nowTime() {
  const latest = Math.max(0, ...stored.map((e) => msOf(e.time)).filter(Number.isFinite));
  return ui.example ? new Date(Math.max(msOf(MISSION.today), latest)) : new Date();
}

function rebuild() {
  machine = createMachine({ cells: CELLS, crew: PEOPLE, state: ui.ship });
  const flight = ui.example ? exampleFlight(CREW) : [];
  const all = [...flight, ...stored].filter((e) => e.kind === 'reading' || e.kind === 'review').sort((a, b) => msOf(a.time) - msOf(b.time));
  for (const ev of all) {
    if (ev.state) machine.setState(ev.state);
    if (ev.kind === 'reading') machine.receive({ ...ev.reading, person: ev.person, time: ev.time, example: Boolean(ev.example) });
    else machine.review(ev.person, ev.time);
  }
  machine.setState(ui.ship);
}

async function keep(event) {
  stored.push(event);
  try {
    await store.append(event);
  } catch {
    toast('Could not save: this record exists only on this screen.');
  }
}

// Every new reading goes through the machine and is saved, exactly like on the technical page.
async function addReading(indicator, value, { source = null, person = ui.person } = {}) {
  const src = source || sourceFor(indicator);
  const event = { v: 1, kind: 'reading', time: new Date().toISOString(), person, state: { ...ui.ship }, reading: { source: src.id, indicator, value } };
  machine.setState(event.state);
  const entry = machine.receive({ ...event.reading, person, time: event.time });
  await keep(event);
  render();
  return entry;
}

// ---------- the person's measures ----------
// The tiles follow the machine's cells, so a new measure in config.js shows up here by itself.
const tileCells = (section) => CELLS.filter((c) => c.section === section && (c.kind === KIND.NUMBER || c.kind === KIND.SELF) && !c.private).map((c) => c.indicator);
const COMPLEX_CELLS = CELLS.filter((c) => c.kind === KIND.COMPLEX).map((c) => c.indicator);
const BODY = tileCells('body');
const PSYCHE = tileCells('psyche');
const SHIP_CELLS = tileCells('env');
const ORDINAL = {
  mood: { 1: 'bad', 2: 'fair', 3: 'good' },
  attitude: { 1: 'sluggish', 2: 'energetic' },
};
const LOW = { mood: 'bad', attitude: 'sluggish' };
const ordinalValue = (ind, v) => { const hit = Object.entries(ORDINAL[ind]).find(([, n]) => n === v); return hit ? Number(hit[0]) : NaN; };

function seriesOf(ownerId, indicator) {
  const cell = cellBy[indicator];
  const list = machine.history(ownerId, indicator);
  if (indicator === 'bp') {
    return [
      { name: 'systolic', color: 'var(--series-1)', points: list.map((x) => ({ t: msOf(x.time), v: Number(x.value.sys), out: !(Number(x.value.sys) < cell.norm.sysBelow) })) },
      { name: 'diastolic', color: 'var(--series-2)', points: list.map((x) => ({ t: msOf(x.time), v: Number(x.value.dia), out: !(Number(x.value.dia) < cell.norm.diaBelow) })) },
    ];
  }
  if (ORDINAL[indicator]) {
    return [{ name: lower(cell.label), color: 'var(--series-1)', points: list.map((x) => ({ t: msOf(x.time), v: ordinalValue(indicator, x.value), out: x.value === LOW[indicator] })).filter((p) => Number.isFinite(p.v)) }];
  }
  return [{ name: lower(cell.label), color: 'var(--series-1)', points: list.map((x) => ({ t: msOf(x.time), v: Number(x.value), out: x.status === STATUS.OUT })).filter((p) => Number.isFinite(p.v)) }];
}

function bandOf(cell, owner) {
  if (cell.normType === 'range') return { min: cell.norm.min, max: cell.norm.max };
  if (cell.normType === 'baseline-percent') {
    const base = owner && owner.baselines ? Number(owner.baselines[cell.baselineKey]) : NaN;
    return Number.isFinite(base) ? { min: (base * cell.norm.minPercent) / 100, max: null } : null;
  }
  return null;
}

// The normal range in words, without the word itself: "36.1 to 37.2", "below 120/80", "7 or more".
function rangeText(cell, owner) {
  if (cell.normType === 'range') {
    const n = cell.norm;
    if (n.minBySex) {
      const v = n.minBySex[owner && owner.sex] ?? Math.min(...Object.values(n.minBySex));
      return `${v} or more`;
    }
    if (n.min !== null && n.max !== null) return `${n.min} to ${n.max}`;
    if (n.min !== null) return `${n.min} or more`;
    return `${n.maxExclusive ? 'below' : 'up to'} ${n.max}`;
  }
  if (cell.normType === 'below-both') return `below ${cell.norm.sysBelow}/${cell.norm.diaBelow}`;
  return normShort(cell, owner);
}

function normShort(cell, owner) {
  if (cell.normType === 'range' || cell.normType === 'below-both') return `normal range ${rangeText(cell, owner)}`;
  if (cell.normType === 'baseline-percent') {
    const b = bandOf(cell, owner);
    return b ? `at least ${fmtVal(b.min)} (${cell.norm.minPercent}% of own level)` : 'no pre-flight level';
  }
  return '';
}

const CAMERA_TEXT = { sleeping: 'asleep', chest_grab: 'hand on chest', chest_grab_ok: 'answered "okay"', chest_grab_help: 'answered "need help"', chest_grab_no_answer: 'no answer' };
function valueText(indicator, value) {
  if (value === null || value === undefined) return '';
  if (indicator === 'bp' && typeof value === 'object') return `${value.sys}/${value.dia}`;
  if (indicator === 'camera') return CAMERA_TEXT[value] || String(value);
  if (indicator === 'bone' && typeof value === 'object') return `${value.hipSpine}% and ${value.neck}%`;
  return fmtVal(value);
}

const whereDoctor = () => (ui.ship.doctorOnBoard ? 'on board' : ui.ship.linkToEarth ? 'on Earth' : 'nowhere: no doctor on board and no link to Earth; what then is still the team\'s open question');

// What one item of the assessment says, in plain words.
function itemText(it, owner) {
  if (it.kind === 'camera') {
    const last = machine.history(owner.id, 'camera').filter((x) => x.status === STATUS.OUT).slice(-1)[0];
    if (last && last.source === 'help-key') return { title: 'Help requested with the Help key', text: `You held the Help key. The automation called the doctor ${whereDoctor()}.`, time: it.time };
    return { title: 'Camera: alarm after the question "Are you okay?"', text: `${it.value === 'chest_grab_help' ? 'You answered that you need help' : 'There was no answer'}. The automation called the doctor ${whereDoctor()}.`, time: it.time };
  }
  if (it.kind === 'mood') return { title: 'Mood and energy', text: `Low check-ins in the last ${LEVEL_RULES.psycheDays} days: ${it.days} ${it.days === 1 ? 'day' : 'days'}. The planned review will look at this.`, time: null };
  const cell = it.cell;
  const last = it.m.last;
  const v = `${valueText(cell.indicator, last.value)} ${cell.unit || ''}`.trim();
  if (it.kind === 'forecast') {
    const c = it.m.forecast.crossing;
    return { title: cell.label, text: `The last reading, ${v}, is still within the normal range, but the line through the readings leaves it ${c.side === 'below' ? 'downwards' : 'upwards'} around ${fmtDate(c.date)}, before landing on ${fmtDate(MISSION.landing)}.`, time: last.time };
  }
  const side = it.m.side === 'below' ? 'below' : 'above';
  if (it.kind === 'standard') return { title: cell.label, text: `${v}: ${side} the NASA standard (${normShort(cell, owner)}).`, time: last.time };
  if (it.kind === 'expected') return { title: cell.label, text: `${v}: ${side} the usual range on Earth (${rangeText(cell, owner)}). ${it.expected.text}`, time: last.time };
  return { title: cell.label, text: `${v}: ${side} the normal range (${rangeText(cell, owner)})${it.m.streak > 1 ? `, ${it.m.streak} readings in a row` : ''}. Reading of ${fmtDT(last.time)}.`, time: last.time };
}

// What to do, by the program's rules (shown in magenta, like NASA's electronic procedures).
function procedureFor(it) {
  switch (it.kind) {
    case 'camera': return ['The automation has already called the doctor.', 'If the alarm was a mistake, tell the doctor with "Message the doctor".', 'The question "Are you okay?" and its waiting time can be changed in the rules.'];
    case 'standard': return ['Repeat the test in the next few days.', 'Show the result to the doctor: the "Message the doctor" button.', 'NASA standard: at least 80% of your own pre-flight level.'];
    case 'forecast': return ['Take a new reading.', 'If the line is confirmed, tell the doctor.', 'The forecast here is a straight line through the readings, not a medical model.'];
    case 'expected': return ['This is a common change in flight; the source is named in the explanation.', 'If you feel unwell, tell the doctor.'];
    case 'mood': return ['The planned review will look at the check-ins.', 'You can start an anonymous session with the AI or write to the doctor on Earth.'];
    default: return ['Repeat the reading.', 'If it is outside the normal range again, press "Analyse with AI" or "Message the doctor".'];
  }
}

// ---------- mission profile ----------
// Where the crew is decides how far help is. Delays are one way; sources: NASA HRP-48021 (Mars, up to about
// 22 minutes one way, with two-week blackouts near solar conjunction) and the Earth-Moon distance (about 1.3 s).
const PROFILES = {
  iss: { name: 'ISS, low Earth orbit', delay: 'under a second', reply: 'a reply can come within minutes', evac: 'a return to Earth is possible within hours' },
  moon: { name: 'Moon (orbit or surface)', delay: 'about 1.3 seconds', reply: 'a reply can come within minutes', evac: 'a return to Earth takes days' },
  mars: { name: 'Mars transit or surface', delay: 'up to about 22 minutes', reply: 'a reply takes at least twice the delay, up to about 44 minutes, and the link can be down for two weeks near solar conjunction', evac: 'no return to Earth for many months' },
};
const profile = () => PROFILES[ui.profile] || PROFILES.iss;

// ---------- "?" explanations ----------
const SELF_SOURCES = ['mood-report', 'attitude-report', 'sleep-rating', 'cycle-log', 'cognition-test'];
function thisValue(owner, last) {
  if (!last) return 'No reading yet.';
  const r = last;
  const when = stamp(last.time, nowTime());
  if (owner && owner.real) return `A real lab result from NASA OSDR (Inspiration4), ${when}.`;
  if (r.source === 'ble-heart-rate') return `Live from your Bluetooth heart rate monitor, ${when}.`;
  if (r.source === 'manual') return `Typed in by hand, ${when}.`;
  if (r.example) return `Made-up example data, shaped like published flight studies (${when}).`;
  if (SELF_SOURCES.includes(r.source)) return `Your own answer, ${when}.`;
  if (r.source === 'camera') return `This computer's camera model, ${when}.`;
  const src = SOURCES.find((s) => s.id === r.source);
  return `Entered on the technical view from a simulated "${src ? src.label : r.source}", ${when}.`;
}
const linkList = (list) => list.flatMap((d, i) => [i ? '; ' : '', d.url ? h('a', { href: d.url, target: '_blank', rel: 'noopener' }, d.name) : d.name, d.maker ? ` (${d.maker})` : '']);
const tipLine = (label, ...content) => h('p', {}, h('b', {}, `${label}: `), ...content);
function measureTip(ind, ownerId) {
  const cell = cellBy[ind];
  if (!cell) return null;
  const pv = PROVENANCE[ind] || {};
  const owner = personById[ownerId] || SHIP;
  const last = machine.history(owner.id, ind).slice(-1)[0] || null;
  const src = sourceFor(ind);
  return h('div', {},
    h('p', { class: 'tp-title' }, cell.label),
    pv.what ? h('p', {}, pv.what) : null,
    pv.iss && pv.iss.length ? tipLine('On the ISS', ...linkList(pv.iss)) : null,
    pv.could && pv.could.length ? tipLine('Could also come from', ...linkList(pv.could)) : null,
    pv.how ? tipLine('How it is measured', pv.how) : null,
    tipLine('Reaches this app', pv.path || (src ? `from a device such as the "${src.label}", simulated on the technical view.` : 'entered by hand.')),
    tipLine('This value', thisValue(owner, last)));
}
function bloodTip(code, personId) {
  const p = personById[personId];
  const x = p && p.real ? realAnalytes(p.code).find((a) => a.code === code) : null;
  const pv = PROVENANCE.blood || {};
  return h('div', {},
    h('p', { class: 'tp-title' }, x ? x.name : 'Blood test'),
    pv.what ? h('p', {}, pv.what) : null,
    pv.iss && pv.iss.length ? tipLine('On the ISS', ...linkList(pv.iss)) : null,
    tipLine('This value', `A real, de-identified lab result of an Inspiration4 crew member from NASA OSDR (OSD-575)${x ? `, lab range ${x.min === null ? '' : x.min} to ${x.max === null ? '' : x.max} ${x.units}` : ''}.`));
}
function systemsTip() {
  const line = (label, value) => h('p', {}, h('b', {}, `${label}: `), value);
  const saved = store ? ({ server: 'on this computer, in the program\'s own files', browser: 'in this browser only (a static copy)', memory: 'only until this page closes (storage is blocked)' }[store.kind] || store.kind) : 'not yet';
  return h('div', {},
    h('p', { class: 'tp-title' }, 'Systems'),
    line('Automation', 'on: every reading is checked against its normal range and the team\'s rules, with or without the AI.'),
    line('AI', ui.ship.aiWorks ? 'the route is on, but no AI model is connected in this version.' : 'off: only the automation works.'),
    line('Mission', `${profile().name}: signal delay ${profile().delay} one way; ${profile().evac}.`),
    line('Link to Earth', ui.ship.linkToEarth ? 'up: messages to Earth go with the next downlink.' : 'down: messages to Earth wait in the outbox.'),
    line('Doctor', ui.ship.doctorOnBoard ? 'on board.' : 'on Earth.'),
    line('Saved', saved),
    line('Sound', ui.muted ? 'off (Settings).' : 'on: needs action sounds a tone, urgent a tone and a voice.'));
}
function tipContent(key) {
  if (key === 's:systems') return systemsTip();
  const [kind, a1, a2] = String(key).split(':');
  if (kind === 'm') return measureTip(a1, a2);
  if (kind === 'b') return bloodTip(a1, a2);
  const t = TIPS[a1];
  if (kind !== 't' || !t) return null;
  return h('div', {}, h('p', { class: 'tp-title' }, t.title), ...t.lines.map((l) => h('p', {}, l)));
}

// ---------- rendering: status line and keys ----------
// Every state has its own icon shape and word, so colour is never the only cue (NASA-STD-3001 Rev F).
const LEVEL_ICON = ['circle-check', 'info', 'triangle-alert', 'octagon-alert'];
const LEVEL_TITLE = LEVEL_WORD.map(cap);
const chip = (lv, text) => h('span', { class: `chip ${LV_CLASS[lv]}`, 'data-tip': 't:level' }, icon(LEVEL_ICON[lv], { size: 16 }), text);
const staleChip = (text) => h('span', { class: 'chip stale' }, icon('clock', { size: 16 }), text);
const btn = (kind, label, onclick, ic = null, extra = {}) => h('button', { type: 'button', class: `btn ${kind}`, onclick, ...extra }, ic ? icon(ic, { size: 18 }) : null, label);
// Short names for the lists; the full name stays on the measure's own page.
const SHORT = { vo2max: 'Aerobic capacity', cabinO2: 'Cabin oxygen', noise: 'Cabin noise', spo2: 'Blood oxygen', sleepQuality: 'Sleep quality', bodyMass: 'Body mass', radiation: 'Radiation dose', mood: 'Mood', attitude: 'Energy' };
const shortLabel = (cell) => SHORT[cell.indicator] || cell.label;
const unitShort = (cell) => (cell.unit || '').replace('of own pre-flight', 'pre-flight');
// When a reading was taken, and how old it is when that matters.
function stamp(t, now) {
  const base = `GMT ${gmtDOY(t)}`;
  if (msOf(t) < msOf(MISSION.launch) && ui.example) return `${base} · before flight`;
  const days = Math.floor((msOf(now) - msOf(t)) / DAY);
  return days >= 3 ? `${base} · ${days} days ago` : base;
}

function renderNav() {
  byId('tabs-in').replaceChildren(...NAV.map(([view, label, ic]) => h('button', {
    type: 'button', class: 'key', 'data-view': view,
    'aria-current': ui.screen === view || (ui.screen === 'detail' && view === (ui.backTo || 'measures')) ? 'page' : null,
    onclick: () => setScreen(view),
  }, icon(ic, { size: 22 }), h('span', {}, label))));
}

function renderBar() {
  const p = ui.person ? personById[ui.person] : null;
  byId('brand').replaceChildren(icon('orbit', { size: 22, label: 'Crew Health Console' }), h('span', { class: p ? 'sr-only' : '' }, 'Crew Health'));
  byId('tabs').hidden = !p;
  byId('who-btn').hidden = !p;
  byId('help-btn').hidden = !p || Boolean(p.real);
  if (p) {
    byId('who-avatar').textContent = p.name.slice(0, 1);
    byId('who-name').textContent = p.name;
    byId('who-btn').setAttribute('aria-label', `${p.name}. Switch person`);
  }
  const now = nowTime();
  if (p && !p.real) byId('met').replaceChildren(h('span', { 'aria-hidden': 'true' }, 'FD '), h('span', { class: 'sr-only' }, 'Flight day '), h('strong', {}, String(Math.floor((msOf(now) - msOf(MISSION.launch)) / DAY) + 1)));
  else byId('met').textContent = p && p.real ? 'Inspiration4, 2021' : '';
  // Quiet and dark: a tag appears only when something is off.
  const tags = [];
  if (p && !p.real && ui.example) tags.push(h('span', { class: 'tag example', 'data-tip': 't:example', tabindex: '0' }, 'Example', h('span', { class: 'tag-long' }, ' data')));
  if (p) tags.push(h('span', { class: 'tag plain systems', 'data-tip': 's:systems', tabindex: '0', role: 'img', 'aria-label': 'Systems: automation, AI, link, doctor, saving, sound' }, icon('cpu', { size: 18 })));
  if (p) {
    if (!ui.ship.linkToEarth) tags.push(h('span', { class: 'tag stale', 'data-tip': 't:nolink' }, icon('unlink', { size: 16 }), 'No link to Earth'));
    if (!ui.ship.aiWorks) tags.push(h('span', { class: 'tag', 'data-tip': 't:aioff' }, icon('ban', { size: 16 }), 'AI off'));
    if (ui.muted) tags.push(h('span', { class: 'tag', 'data-tip': 't:soundoff' }, icon('bell-off', { size: 16 }), 'Sound off'));
    if (camStop) tags.push(h('span', { class: 'tag plain', 'data-tip': 't:camon' }, icon('camera', { size: 16 }), 'Camera on'));
  }
  byId('sys-summary').replaceChildren(...tags);
  // The Messages key takes the colour of the highest active level, like the ISS "Home" key.
  const box = byId('alerts-btn');
  box.hidden = !p || p.real;
  if (p && !p.real) {
    const list = alertsFor(p.id);
    const unseen = list.filter((x) => !ui.seen.has(x.id)).length;
    const top = list.length ? Math.max(...list.map((x) => x.level)) : LEVEL.FINE;
    soundAlerts(list);
    box.className = `annunciator ${list.length ? LV_CLASS[top] : ''}`;
    if (!list.length) box.replaceChildren(icon('bell', { size: 18 }), h('span', { class: 'ann-word' }, 'No messages'));
    else box.replaceChildren(icon(LEVEL_ICON[top], { size: 18 }), h('span', { class: 'ann-word' }, 'Messages'), h('b', {}, unseen ? `${unseen} new` : String(list.length)));
    box.setAttribute('aria-label', list.length ? `Messages: ${list.length}, ${unseen} new, highest level ${LEVEL_WORD[top]}` : 'No messages');
  }
  renderNav();
}

// ---------- rendering: sign-in ----------
function renderLogin() {
  const initials = (p) => (p.real ? String(p.code || '').replace(/^C0*/, 'C') : /\d$/.test(p.name) ? `C${p.name.slice(-1)}` : p.name.slice(0, 1));
  const card = (p) => h('button', { type: 'button', class: 'person', onclick: () => choosePerson(p.id) },
    h('span', { class: 'avatar' }, initials(p)), h('b', {}, p.real ? `Participant ${p.code}` : p.name),
    h('span', {}, p.real ? 'Real blood tests, 2021' : 'Example crew member'));
  byId('people-crew').replaceChildren(...CREW.map(card));
  byId('people-real').replaceChildren(...REAL.map(card));
}

function choosePerson(id) {
  ui.person = id;
  ui.screen = 'home';
  ui.detail = null;
  ui.find = '';
  render();
  window.scrollTo(0, 0);
}

// ---------- rendering: Today ----------
// The team's front side: one dated message about body and mind, a short explanation, buttons, a choice.
const KEY_NUMBERS = ['pulse', 'bp', 'spo2', 'temp', 'sleep', 'resp'];
const offerDismissed = new Set();

function renderHome() {
  const p = personById[ui.person];
  if (p.real) return renderRealHome(p);
  const now = nowTime();
  const a = assess({ machine, person: p, cells: CELLS, mission: MISSION, now });
  const top = Math.max(a.body.level, a.psyche.level);
  byId('today').className = `card today ${LV_CLASS[top]}`;
  byId('today-label').textContent = 'Your health today';
  byId('today-time').textContent = `Updated GMT ${gmtDOY(now)}`;
  byId('today-title').textContent = headline(fmtDate(now), a.body.level, a.psyche.level);
  const chips = [];
  if (a.body.level) chips.push(chip(a.body.level, `Body: ${LEVEL_WORD[a.body.level]}`));
  if (a.psyche.level) chips.push(chip(a.psyche.level, `Mind: ${LEVEL_WORD[a.psyche.level]}`));
  byId('today-chips').replaceChildren(...chips);
  byId('today-chips').hidden = !chips.length;

  // The short explanation, in the same order as Messages: level first, then outside the range now, then forecasts.
  const all = [...a.body.items, ...a.psyche.items].sort((x, y) => y.level - x.level);
  const items = all.length === 4 ? all : all.slice(0, 3);
  const short = (it) => {
    if (it.kind === 'camera') return 'The automation called the doctor';
    if (it.kind === 'mood') return `${it.days} low days in the last two weeks`;
    if (it.kind === 'forecast') return `Forecast: in the normal range now, may leave it around ${fmtDate(it.m.forecast.crossing.date)}`;
    const v = `${valueText(it.cell.indicator, it.m.last.value)} ${it.cell.unit || ''}`.trim();
    const where = it.kind === 'standard' ? 'the NASA standard' : 'the normal range';
    return `${v}, ${it.m.side === 'below' ? 'below' : 'above'} ${where}${it.m.streak > 1 && it.kind === 'out' ? ` in the last ${it.m.streak} readings` : ''}${it.kind === 'expected' ? ' (common in flight)' : ''}`;
  };
  const name = (it) => (it.cell ? it.cell.label : it.kind === 'mood' ? 'Mood and energy' : 'Camera');
  const open = (it) => (it.cell ? openDetail(it.cell.indicator) : it.kind === 'mood' ? openDetail('mood') : setScreen('alerts'));
  byId('today-reasons').hidden = !items.length;
  byId('today-reasons').replaceChildren(
    ...items.map((it) => h('li', {}, h('button', { type: 'button', class: 'reason', 'data-tip': it.cell ? `m:${it.cell.indicator}:${p.id}` : it.kind === 'mood' ? `m:mood:${p.id}` : 'm:camera:' + p.id, onclick: () => open(it) },
      icon(LEVEL_ICON[it.level], { size: 20, cls: `lvc${it.level}`, label: LEVEL_WORD[it.level] }),
      h('span', { class: 'what' }, h('b', {}, name(it)), h('span', {}, short(it))),
      icon('chevron-right', { size: 18, cls: 'chev' })))),
    ...(all.length > items.length ? [h('li', { class: 'more' }, h('button', { type: 'button', class: 'link', onclick: () => setScreen('alerts') }, `${all.length - items.length} more in Messages`))] : []));

  // The team's buttons. Body: "Details", then "Analyse with AI" and "Message the doctor".
  const acts = [];
  if (a.body.level > LEVEL.FINE) {
    const first = a.body.items.find((x) => x.cell);
    acts.push(btn('primary', 'Details', () => (first ? openDetail(first.cell.indicator) : setScreen('alerts')), null, { 'data-tip': 't:details' }));
    acts.push(aiButton('Analyse with AI', 'body', a));
    acts.push(btn('secondary', 'Message the doctor', () => openDoctor(a, 'body'), 'stethoscope', { 'data-tip': 't:doctor' }));
  }
  byId('today-actions').replaceChildren(...acts);
  byId('today-actions').hidden = !acts.length;

  // Mind: the team's AI psychologist offers to talk; the choice stays with the person.
  byId('today-advice').replaceChildren(...(a.psyche.level > LEVEL.FINE ? [mindChoice(p, a, a.body.level === LEVEL.FINE)] : []));
  byId('today-advice').hidden = a.psyche.level === LEVEL.FINE;
  byId('today-note').textContent = '';
  byId('today-note').hidden = true;

  renderCheckin(p, now, top);
  renderComingUp(p, now);
  const keys = KEY_NUMBERS.filter((ind) => cellBy[ind] && machine.history(p.id, ind).length).slice(0, 4);
  byId('keynum-rows').replaceChildren(...keys.map((ind) => measureRow(p, ind, a, now)));
  renderGroups(p, a, now);
}

function aiButton(label, kind, a, primary = false) {
  const off = !ui.ship.aiWorks;
  const b = h('button', { type: 'button', class: `btn ${primary ? 'primary' : 'secondary'}`, 'data-tip': kind === 'psyche' ? 't:aisession' : 't:ai', 'aria-disabled': off ? 'true' : null, onclick: () => (off ? toast('The AI is off: only the automation is working.') : openAi(kind, a)) }, icon('sparkles', { size: 18 }), label);
  return off ? h('span', { class: 'btn-wrap' }, b, h('span', { class: 'why' }, 'AI unavailable now')) : b;
}

// The team's words for the AI psychologist (translated): "Hey <name>, I noticed from your answers that ...
// How about talking anonymously about what is bothering you? Or, if you wish, I can send the results to the doctor."
function mindChoice(p, a, primaryFirst) {
  const choices = h('div', { class: 'actions' },
    aiButton('Start an anonymous session with AI', 'psyche', a, primaryFirst),
    btn('secondary', 'Tell the doctor on Earth', () => openDoctor(a, 'psyche'), 'stethoscope', { 'data-tip': 't:tellDoctor' }),
    btn('secondary', 'Advice and articles', () => openAdvice(), 'list', { 'data-tip': 't:advice' }));
  if (offerDismissed.has(p.id)) return h('div', { class: 'advice' }, choices);
  return h('div', { class: 'advice' },
    h('p', { class: 'who-says' }, 'AI support (not a psychologist) · not connected yet'),
    h('blockquote', {}, `Hey ${p.name}, I noticed from your check-ins that the last days have been hard. How about talking anonymously about what is bothering you? Or, if you wish, I can send the results of these check-ins to the doctor.`),
    choices,
    h('div', { class: 'actions' }, btn('secondary small', 'Not now', () => { offerDismissed.add(p.id); renderHome(); })),
    h('p', { class: 'note' }, "The team's idea: this conversation is not recorded or read, and the AI is there day and night, unlike doctors. Which AI it is, the team decides."));
}

// ---------- coming up: what is due, from the medical routine of an ISS flight ----------
// Cadences: private medical conference weekly and private psychological conference every two weeks (NASA BHP and
// CHP-IDSP, 2024 and 2025); thinking test monthly (NASA OCHMO-TB-016, WinSCAT); eye checks on flight days 30 and 90
// and 30 days before return (NASA JSC 2018). The dates below are an example schedule, marked as such.
function renderComingUp(p, now) {
  const card = byId('comingup');
  if (!p || p.real || !ui.example) { card.hidden = true; return; }
  const day = Math.floor((msOf(now) - msOf(MISSION.launch)) / DAY) + 1;
  const toLanding = Math.max(0, Math.ceil((msOf(MISSION.landing) - msOf(now)) / DAY));
  const landingDay = day + toLanding;
  const every = (n, offset = 0) => { const d = (n - ((day + offset) % n)) % n; return d === 0 ? n : d; };
  const eyeDays = [30, 90, landingDay - 30].filter((d) => d > day);
  const items = [
    { ic: 'stethoscope', what: 'Private medical conference with your flight surgeon (weekly)', in: every(7, 3), act: () => openPmc(p) },
    { ic: 'message-square', what: 'Private talk with your psychologist (every 2 weeks)', in: every(14, 5) },
    { ic: 'zap', what: 'Thinking test (monthly)', in: every(30, 11) },
    eyeDays.length ? { ic: 'scan-line', what: 'Eye check: vision, retina scan (OCT)', in: eyeDays[0] - day } : { ic: 'scan-line', what: 'Eye check after landing', in: toLanding + 1 },
  ].sort((a, b) => a.in - b.in).slice(0, 3);
  const when = (n) => (n === 1 ? 'tomorrow' : `in ${n} days`);
  byId('comingup-note').textContent = 'Example schedule';
  byId('comingup-list').replaceChildren(...items.map((it) => h('li', {}, icon(it.ic, { size: 18 }), h('span', {}, it.what, it.act ? [' ', btn('secondary small', 'Prepare', it.act, null, { 'data-tip': 't:pmc' })] : null), h('span', { class: 'when' }, when(it.in)))));
  card.hidden = false;
}

// A one-page summary of the last 7 days for the private medical conference; the person edits it and decides.
function pmcSummary(p, now) {
  const since = msOf(now) - 7 * DAY;
  const lines = [`For my private medical conference. ${p.name}, flight day ${Math.floor((msOf(now) - msOf(MISSION.launch)) / DAY) + 1}, the last 7 days:`];
  const nums = ['pulse', 'bp', 'spo2', 'temp', 'resp', 'sleep', 'fluid'];
  for (const ind of nums) {
    const cell = cellBy[ind];
    if (!cell) continue;
    const list = machine.history(p.id, ind).filter((x) => msOf(x.time) >= since);
    if (!list.length) continue;
    if (ind === 'bp') {
      const sys = list.map((x) => Number(x.value.sys));
      const dia = list.map((x) => Number(x.value.dia));
      lines.push(`- Blood pressure: ${list.length} readings, ${Math.min(...sys)}/${Math.min(...dia)} to ${Math.max(...sys)}/${Math.max(...dia)} mmHg${list.some((x) => x.status === STATUS.OUT) ? ', some outside the normal range' : ''}.`);
      continue;
    }
    const v = list.map((x) => Number(x.value)).filter(Number.isFinite);
    if (!v.length) continue;
    const avg = v.reduce((s, x) => s + x, 0) / v.length;
    const r = (x) => (Math.abs(x) >= 100 ? String(Math.round(x)) : fmtVal(x));
    lines.push(`- ${cell.label}: ${v.length} readings, average ${r(avg)} ${cell.unit || ''}, from ${r(Math.min(...v))} to ${r(Math.max(...v))}${list.some((x) => x.status === STATUS.OUT) ? ', some outside the normal range' : ''}.`.replace(/ +\./g, '.').replace(/ +,/g, ','));
  }
  const count = (ind, val) => machine.history(p.id, ind).filter((x) => msOf(x.time) >= since && x.value === val).length;
  const moods = ['good', 'fair', 'bad'].map((v) => `${count('mood', v)} ${v}`).join(', ');
  lines.push(`- Check-ins: mood ${moods}; energy ${count('attitude', 'energetic')} energetic, ${count('attitude', 'sluggish')} sluggish.`);
  const active = alertsFor(p.id).filter((x) => x.system !== 'Ship');
  if (active.length) lines.push(`- Flagged by the program: ${active.map((x) => `${x.title} (${LEVEL_WORD[x.level]})`).join('; ')}.`);
  lines.push('', 'What I want to talk about:', '');
  return lines.join('\n');
}
function openPmc(p) {
  const area = h('textarea', { 'aria-label': 'Summary for the private medical conference' });
  area.value = pmcSummary(p, nowTime());
  openPanel('Prepare for your private medical conference', [
    h('p', {}, 'A summary of your last 7 days, drafted by the automation. Change anything; add what you want to talk about. Nothing is sent unless you press Send.'),
    area,
    h('p', { class: 'note' }, 'NASA flight surgeons hold a private medical conference with each crew member every week, about 15 minutes.'),
  ], [btn('primary', 'Send to my flight surgeon', async () => {
    const to = ui.ship.doctorOnBoard ? 'doctor-onboard' : 'doctor-earth';
    await keep({ v: 1, kind: 'report', time: new Date().toISOString(), person: ui.person, state: { ...ui.ship }, report: { to, text: area.value.slice(0, 6000), topic: 'pmc' } });
    closePanel();
    toast(to === 'doctor-earth' ? (ui.ship.linkToEarth ? 'Saved in the outbox: it goes with the next downlink.' : 'Saved in the outbox: it goes when the link is back.') : 'Saved for the doctor on board.');
    render();
  }, 'send')]);
}

// ---------- morning check-in ----------
function renderCheckin(p, now, top = LEVEL.FINE) {
  const day = new Date(now).toDateString();
  const todays = (ind) => machine.history(p.id, ind).filter((x) => new Date(x.time).toDateString() === day).slice(-1)[0];
  const m = todays('mood');
  const e = todays('attitude');
  const s = todays('sleepQuality');
  const done = [m && `Mood: ${cap(m.value)}`, e && `Energy: ${cap(e.value)}`, s && `Sleep quality: ${s.value} of 7`].filter(Boolean);
  const open = ui.checkinOpen;
  byId('ci-form').hidden = !open;
  byId('ci-sub').textContent = done.length ? `Checked in today. ${done.join(' · ')}` : 'Three quick questions: mood, energy, last night\'s sleep.';
  byId('ci-start-slot').replaceChildren(...(open ? [] : [done.length
    ? btn('secondary small', 'Change', () => { ui.checkinOpen = true; renderCheckin(p, now, top); })
    : btn(top === LEVEL.FINE ? 'primary' : 'secondary', 'Start', () => { ui.checkinOpen = true; renderCheckin(p, now, top); })]));
  const seg = (id, key, options) => byId(id).replaceChildren(...options.map(([value, label]) => h('button', {
    type: 'button', 'aria-pressed': String(ui.checkin[key] === value), onclick: () => { ui.checkin[key] = ui.checkin[key] === value ? null : value; renderCheckin(p, now, top); },
  }, ui.checkin[key] === value ? icon('check', { size: 16 }) : null, label)));
  seg('ci-mood', 'mood', [['bad', 'Bad'], ['fair', 'Fair'], ['good', 'Good']]);
  seg('ci-attitude', 'attitude', [['sluggish', 'Sluggish'], ['energetic', 'Energetic']]);
  seg('ci-sleep', 'sleepQuality', [1, 2, 3, 4, 5, 6, 7].map((n) => [n, String(n)]));
  const any = Boolean(ui.checkin.mood || ui.checkin.attitude || ui.checkin.sleepQuality);
  byId('ci-send').setAttribute('aria-disabled', any ? 'false' : 'true');
}

async function sendCheckin() {
  const c = ui.checkin;
  if (!c.mood && !c.attitude && !c.sleepQuality) { toast('Choose at least one answer.'); return; }
  if (c.mood) await addReading('mood', c.mood);
  if (c.attitude) await addReading('attitude', c.attitude);
  if (c.sleepQuality) await addReading('sleepQuality', c.sleepQuality);
  ui.checkin = { mood: null, attitude: null, sleepQuality: null };
  ui.checkinOpen = false;
  toast('Check-in saved. The planned review will look at it.');
  render();
}

// ---------- measures as telemetry rows ----------
// A row: the name and the time of the last reading on the left; the value and unit on the right.
// A normal row carries no colour. An off row: the value in a tinted field with an arrow, and the level word.
function measureRow(owner, indicator, a, now) {
  const cell = cellBy[indicator];
  const last = machine.history(owner.id, indicator).slice(-1)[0] || null;
  const item = a ? [...a.body.items, ...a.psyche.items].find((x) => x.cell && x.cell.indicator === indicator) : null;
  let level = item ? item.level : LEVEL.FINE;
  if (owner === SHIP && last && last.status === STATUS.OUT) level = LEVEL.ATTENTION;
  const m = cell.kind === KIND.NUMBER ? measureState({ machine, person: owner, cell, mission: MISSION, now }) : null;
  const stale = Boolean(m && m.stale);
  const out = Boolean(last && last.status === STATUS.OUT);
  const forecast = Boolean(item && item.kind === 'forecast');
  const kids = [h('b', { class: 'r-name' }, shortLabel(cell))];
  if (cell.onlyOnEarth && !last) kids.push(h('span', { class: 'r-none' }, icon('ban', { size: 16 }), 'Not measured in flight'));
  else if (!last) kids.push(h('span', { class: 'r-none' }, 'No readings yet'));
  else {
    const raw = valueText(indicator, last.value);
    const word = indicator === 'sleepQuality' ? `${raw} of 7` : ORDINAL[indicator] ? cap(raw) : raw;
    const isWord = !/^[0-9.,/% -]+$/.test(String(word));
    const hasUnit = cell.kind === KIND.NUMBER && Boolean(cell.unit);
    const arrow = out && m && m.side ? icon(m.side === 'below' ? 'arrow-down' : 'arrow-up', { size: 16, stroke: 2.4, label: m.side === 'below' ? 'below the normal range' : 'above the normal range' }) : null;
    const tint = out && level ? `lvc${level}` : '';
    kids.push(h('span', { class: `r-num ${isWord ? 'word' : ''} ${hasUnit ? '' : 'nounit'} ${tint}` }, word, arrow));
    if (hasUnit) kids.push(h('span', { class: 'r-unit' }, unitShort(cell)));
  }
  kids.push(h('span', { class: 'r-time' }, last ? stamp(last.time, now) : cell.onlyOnEarth ? 'Before and after flight only' : ''));
  if (forecast) kids.push(h('span', { class: 'r-state lvc1' }, icon('info', { size: 14 }), 'Forecast: may leave the range'));
  else if (level) kids.push(h('span', { class: `r-state lvc${level}` }, icon(LEVEL_ICON[level], { size: 14 }), LEVEL_TITLE[level]));
  else if (stale && last) kids.push(h('span', { class: 'r-state lvc-stale' }, icon('clock', { size: 14 }), `Old data, ${ageText(last.time, now)}`));
  kids.push(icon('chevron-right', { size: 18, cls: 'chev' }));
  return rowWrap(h('button', { type: 'button', class: `row ${level ? LV_CLASS[level] : stale ? 'stale' : ''}`, 'data-ind': indicator, 'data-tip': `m:${indicator}:${owner.id}`, onclick: () => openDetail(indicator) }, ...kids), `m:${indicator}:${owner.id}`, cell.label);
}
const rowWrap = (row, key, label) => h('div', { class: 'row-wrap' }, row, tipButton(key, label));

function cameraRow(owner) {
  const now = nowTime();
  const list = machine.history(owner.id, 'camera');
  const last = list[list.length - 1];
  const level = last && last.status === STATUS.OUT && msOf(now) - msOf(last.time) < LEVEL_RULES.cameraHours * 60 * 60 * 1000 ? LEVEL.URGENT : LEVEL.FINE;
  return rowWrap(h('button', { type: 'button', class: `row ${LV_CLASS[level]}`, 'data-ind': 'camera', 'data-tip': 't:camera', onclick: () => setScreen('setup') },
    h('b', { class: 'r-name' }, 'Camera'),
    camStop ? h('span', { class: 'r-num word nounit' }, 'Watching') : h('span', { class: 'r-none' }, icon('camera-off', { size: 16 }), 'Camera off'),
    h('span', { class: 'r-time text' }, last ? `Last event: ${CAMERA_TEXT[last.value] || last.value}, ${stamp(last.time, now)}` : 'No events yet. Video is never stored.'),
    level ? h('span', { class: 'r-state lvc3' }, icon('octagon-alert', { size: 14 }), 'Urgent') : null,
    icon('chevron-right', { size: 18, cls: 'chev' })), 't:camera', 'the camera');
}

// Complex data: an image or a tracing goes to the AI or a doctor; the row shows what came in last.
function complexRow(owner, indicator) {
  const cell = cellBy[indicator];
  const now = nowTime();
  const last = machine.history(owner.id, indicator).slice(-1)[0] || null;
  return rowWrap(h('button', { type: 'button', class: 'row', 'data-ind': indicator, 'data-tip': `m:${indicator}:${owner.id}`, onclick: () => openPanel(cell.label, [
    h('p', {}, `How the machine handles it: ${cell.normText}. With the AI working it goes to the AI; when the AI analyses it and when a doctor does is still the team's open question.`),
    cell.availability ? h('p', {}, cell.availability) : null,
    h('p', { class: 'note' }, 'Devices are simulated on the technical view, where an image or a tracing can be sent.'),
  ]) },
    h('b', { class: 'r-name' }, cell.label),
    last ? h('span', { class: 'r-num word nounit' }, 'Received') : h('span', { class: 'r-none' }, 'Nothing yet'),
    h('span', { class: 'r-time' }, last ? stamp(last.time, now) : ''),
    last ? h('span', { class: 'r-state' }, 'Needs analysis') : null,
    icon('chevron-right', { size: 18, cls: 'chev' })), `m:${indicator}:${owner.id}`, cell.label);
}

// The menstrual cycle card, private to the person ("like Flo, but for astronauts", the team's words).
function cycleCard(p, now) {
  if (p.sex !== 'F') return null;
  const s = cycleSummary(machine.history(p.id, 'cycle'), now);
  const lows = new Map();
  for (const [ind, low] of [['mood', 'bad'], ['attitude', 'sluggish']]) {
    for (const x of machine.history(p.id, ind)) {
      const day = new Date(x.time).toISOString().slice(0, 10);
      lows.set(day, Boolean(lows.get(day)) || x.value === low);
    }
  }
  const phases = lowDaysByPhase(s.starts, [...lows.entries()].map(([d, low]) => [`${d}T12:00:00Z`, low]));
  const facts = [];
  if (s.suppressed) facts.push("You chose to suppress your periods. Many astronauts do; the choice is yours and your flight surgeon's.");
  else if (s.cycleDay) facts.push(`Cycle day ${s.cycleDay}${s.average ? ` · average cycle ${s.average} days` : ''}${s.periodDays ? ` · period about ${s.periodDays} days` : ''}${s.nextExpected ? ` · next period expected around ${fmtDate(s.nextExpected)}` : ''}.`);
  else facts.push('No period logged yet.');
  if (s.flags.includes('long-cycles')) facts.push(`The last cycles were longer than ${CYCLE_RULES.longCycleDays} days. The Endocrine Society advises a check-up when cycles are consistently that long.`);
  if (s.flags.includes('no-period')) facts.push('No period for more than 3 months. The Endocrine Society advises a check-up, after other causes are ruled out.');
  if (s.flags.includes('cycle-outside-range')) facts.push(`The last cycle was outside the usual ${CYCLE_RULES.normalMin} to ${CYCLE_RULES.normalMax} days (ACOG).`);
  if (s.flags.includes('cycle-varies')) facts.push(`Your recent cycles differ by more than ${CYCLE_RULES.varyMax} days; ACOG counts that as irregular.`);
  if (s.flags.includes('long-period')) facts.push(`The last period lasted more than ${CYCLE_RULES.periodMax} days; ACOG counts that as abnormal bleeding.`);
  const table = s.starts.length > 1 ? h('details', { class: 'more' }, h('summary', {}, icon('chevron-right', { size: 18 }), 'Mood and energy across your cycle'),
    h('div', {}, h('p', { class: 'note' }, 'Your own days, no conclusion drawn.'), h('div', { class: 'table-wrap' }, h('table', {},
      h('thead', {}, h('tr', {}, h('th', {}, 'Cycle days'), h('th', {}, 'Days with check-ins'), h('th', {}, 'Days with a low check-in'))),
      h('tbody', {}, ...phases.map((ph) => h('tr', {}, h('td', {}, ph.to > 30 ? `${ph.from} and later` : `${ph.from} to ${ph.to}`), h('td', {}, String(ph.days)), h('td', {}, String(ph.low))))))))) : null;
  return h('section', { class: 'group', 'data-terms': 'menstrual cycle period private' },
    h('div', { class: 'group-head' }, h('h2', { id: 'cycle-title' }, 'Menstrual cycle'), h('p', {}, 'Private: not sent to anyone unless you choose to.')),
    h('section', { class: 'card', 'aria-labelledby': 'cycle-title', 'data-terms': 'menstrual cycle period private' },
    h('div', { class: 'prose' }, ...facts.map((x) => h('p', {}, x))),
    h('div', { class: 'actions' },
      btn('secondary', 'Period started today', () => addReading('cycle', 'period_start')),
      btn('secondary', 'Period ended today', () => addReading('cycle', 'period_end')),
      btn('secondary', s.suppressed ? 'I no longer suppress my periods' : 'I suppress my periods', () => addReading('cycle', s.suppressed ? 'suppression_off' : 'suppression_on'))),
    table,
    h('p', { class: 'note' }, `Doctors on Earth treat the cycle as a vital sign; a typical cycle is ${CYCLE_RULES.normalMin} to ${CYCLE_RULES.normalMax} days and a period lasts up to ${CYCLE_RULES.periodMax} days (ACOG). The next-period date is a plain average of your last cycles, not a medical model.`)));
}

// Fixed groups, always in the same order, so each measure keeps its place. A new measure in config.js
// that is not listed here still shows up, under "Other measures".
const GROUPS = [
  ['Vital signs', null, ['pulse', 'bp', 'spo2', 'temp', 'resp']],
  ['Sleep, food and fluid', null, ['sleep', 'fluid', 'glucose', 'bodyMass']],
  ['Slow changes over the flight', 'Checked every few weeks, or carried over the whole flight.', ['vo2max', 'strength', 'bone', 'eyePressure', 'hearing', 'radiation']],
  ['Mind', 'Your daily check-ins.', ['mood', 'attitude', 'sleepQuality', 'cognition']],
  ['Images, tracings and camera', 'These go to the AI or a doctor.', ['xray', 'ecg', 'ultrasound', 'camera']],
];
// Everyday words a person may type in "Find a measure".
const WORDS = {
  pulse: 'pulse heart rate hr bpm heartbeat', bp: 'bp blood pressure systolic diastolic hypertension', spo2: 'oxygen o2 sats saturation spo2 pulse ox',
  temp: 'temperature fever temp', resp: 'breathing respiration breaths', sleep: 'sleep hours rest', fluid: 'water drink fluid hydration',
  glucose: 'sugar glucose blood sugar', bodyMass: 'weight mass body', vo2max: 'fitness aerobic vo2 cardio exercise', strength: 'muscle strength',
  bone: 'bone density dexa', eyePressure: 'eye vision iop', hearing: 'ear hearing audiogram', radiation: 'radiation dose msv dosimeter',
  mood: 'mood feeling', attitude: 'energy tired fatigue', sleepQuality: 'sleep quality rest', cognition: 'thinking cognition memory test',
  xray: 'x-ray xray image', ecg: 'ecg ekg heart tracing', ultrasound: 'ultrasound echo scan image', camera: 'camera video chest sleep',
  co2: 'co2 carbon dioxide air', cabinO2: 'oxygen o2 air', cabinPressure: 'pressure cabin air', noise: 'noise sound loud db', cabinTemp: 'temperature cabin air',
};

function renderGroups(p, a, now) {
  const shipA = assessShip({ machine, ship: SHIP, cells: CELLS, mission: MISSION, now });
  const shipItems = { body: { items: shipA.items }, psyche: { items: [] } };
  const listed = new Set(GROUPS.flatMap((g) => g[2]));
  const others = [...BODY, ...PSYCHE].filter((ind) => !listed.has(ind));
  const rowFor = (ind) => (ind === 'camera' ? cameraRow(p) : COMPLEX_CELLS.includes(ind) ? complexRow(p, ind) : cellBy[ind] ? measureRow(p, ind, a, now) : null);
  const group = (title, hint, rows) => {
    const real = rows.filter(Boolean);
    const flaggedHere = real.some((w) => w.querySelector('.row.lv1, .row.lv2, .row.lv3, .row.stale'));
    const foldable = !flaggedHere;
    const open = !foldable || ui.openGroups.has(title);
    const list = h('div', { class: 'rows', hidden: open ? null : true }, ...real);
    const toggle = foldable ? h('button', { type: 'button', class: 'fold', 'aria-expanded': String(open), onclick: (e) => {
      const nowOpen = list.hidden;
      list.hidden = !nowOpen;
      if (nowOpen) ui.openGroups.add(title); else ui.openGroups.delete(title);
      e.currentTarget.setAttribute('aria-expanded', String(nowOpen));
      e.currentTarget.lastChild.textContent = nowOpen ? 'Hide' : `Show ${real.length}`;
    } }, h('span', { class: 'fold-note' }, icon('circle-check', { size: 16 }), 'Nothing to look at'), h('span', { class: 'fold-act' }, open ? 'Hide' : `Show ${real.length}`)) : null;
    return h('section', { class: 'group', 'data-foldable': foldable ? '1' : null, 'data-title': title },
      h('div', { class: 'group-head' }, h('h2', {}, title), toggle || (hint ? h('p', {}, hint) : null)),
      foldable && hint ? h('p', { class: 'note' }, hint) : null,
      list);
  };
  const blocks = GROUPS.flatMap(([title, hint, list]) => [group(title, hint, list.map(rowFor)), title === 'Mind' ? cycleCard(p, now) : null]).filter(Boolean);
  if (others.length) blocks.push(group('Other measures', null, others.map(rowFor)));
  blocks.push(group('Cabin air', 'Shared by the whole crew.', SHIP_CELLS.map((ind) => measureRow(SHIP, ind, shipItems, now))));
  byId('groups').replaceChildren(...blocks);
  // One line at the top names what needs attention; each name jumps to its row.
  const flagged = [...a.body.items, ...a.psyche.items, ...shipA.items].filter((x) => x.cell);
  const needs = byId('needs');
  needs.hidden = !flagged.length;
  needs.replaceChildren(...(flagged.length ? [h('span', {}, 'To look at:'), ...flagged.map((x) => h('button', { type: 'button', class: 'link ink', onclick: () => {
    const row = document.querySelector(`#groups .row[data-ind="${x.cell.indicator}"]`);
    if (row) { row.scrollIntoView({ block: 'center' }); row.focus({ preventScroll: true }); }
  } }, icon(LEVEL_ICON[x.level], { size: 16, cls: `lvc${x.level}` }), x.cell.section === 'env' ? `${x.cell.label} (ship)` : x.cell.label))] : []));
  byId('measures-sub').textContent = 'Press a measure to see its history.';
  applyFind();
}

function applyFind() {
  const q = ui.find.trim().toLowerCase();
  byId('find').value = ui.find;
  byId('find-clear').hidden = !q;
  let shown = 0;
  for (const g of byId('groups').querySelectorAll('.group')) {
    let inGroup = 0;
    for (const wrap of g.querySelectorAll('.row-wrap')) {
      const row = wrap.querySelector('.row');
      const ind = row.dataset.ind || '';
      const hay = `${row.querySelector('.name b') ? row.querySelector('.name b').textContent : ''} ${WORDS[ind] || ''}`.toLowerCase();
      const hit = !q || hay.includes(q);
      wrap.hidden = !hit;
      if (hit) inGroup += 1;
    }
    const terms = g.dataset.terms || '';
    g.hidden = Boolean(q) && !inGroup && !(terms && terms.includes(q));
    const list = g.querySelector(':scope > .rows');
    if (list && g.dataset.foldable) list.hidden = q ? false : !ui.openGroups.has(g.dataset.title);
    if (!g.hidden) shown += 1;
  }
  let empty = byId('find-empty');
  if (!empty) { empty = h('p', { class: 'empty-find', id: 'find-empty' }, 'No measure matches that word. Try another one.'); byId('groups').append(empty); }
  empty.hidden = !q || shown > 0;
}

// ---------- Inspiration4: real blood tests before and after a real flight ----------
// Dates from NASA OSDR's own record of OSD-575: "Mission Start 09/16/2021", "Mission End 09/18/2021".
// The timepoints are counted in days from launch (L-) and from return (R+); midday is used for both dates.
const I4 = { launch: '2021-09-16T12:00:00Z', landing: '2021-09-18T12:00:00Z' };
const tpTime = (tp) => {
  const m = /^([LR])([+-])(\d+)$/.exec(tp);
  if (!m) return NaN;
  const base = msOf(m[1] === 'L' ? I4.launch : I4.landing);
  return base + (m[2] === '+' ? 1 : -1) * Number(m[3]) * DAY;
};
const tpText = (tp) => {
  const m = /^([LR])([+-])(\d+)$/.exec(tp);
  if (!m) return tp;
  return m[1] === 'L' ? `${m[3]} days before launch` : `${m[3]} ${m[3] === '1' ? 'day' : 'days'} after return`;
};

function realAnalytes(code) {
  const s = INSPIRATION4.subjects[code];
  const map = new Map();
  for (const tp of INSPIRATION4.timepoints) {
    for (const a of (s.panels[tp] || [])) {
      if (!map.has(a.code)) map.set(a.code, { code: a.code, name: a.nameEn || a.name, units: a.units, min: a.min, max: a.max, points: [] });
      const v = Number(a.value);
      if (Number.isFinite(v)) map.get(a.code).points.push({ t: tpTime(tp), v, tp, out: (a.min !== null && v < a.min) || (a.max !== null && v > a.max) });
    }
  }
  return [...map.values()].filter((x) => x.points.length);
}

function renderRealHome(p) {
  const analytes = realAnalytes(p.code);
  const outNow = analytes.filter((x) => { const l = x.points[x.points.length - 1]; return l && l.out; });
  byId('today').className = `card today ${outNow.length ? 'lv1' : ''}`;
  byId('today-label').textContent = 'Your blood tests';
  byId('today-time').textContent = 'Real de-identified data, NASA OSDR';
  byId('today-title').textContent = 'Blood tests before and after a real flight, up to half a year after return.';
  byId('today-chips').hidden = false;
  byId('today-chips').replaceChildren(outNow.length ? chip(LEVEL.ATTENTION, `Outside the lab range in the last test: ${outNow.length}`) : h('span', { class: 'chip neutral' }, icon('circle-check', { size: 16 }), 'All within the lab range in the last test'));
  byId('today-reasons').hidden = true;
  byId('today-reasons').replaceChildren();
  byId('today-advice').replaceChildren();
  byId('today-advice').hidden = true;
  byId('today-actions').hidden = false;
  byId('today-actions').replaceChildren(btn('primary', 'See all blood values', () => setScreen('measures')));
  byId('today-note').className = 'note';
  byId('today-note').hidden = false;
  byId('today-note').textContent = 'Seven blood draws: 92, 44 and 3 days before launch, and 1, 45, 82 and 194 days after return. Blood tests alone do not tell the condition of body and mind, so there is no status message here.';
  const rows = analytes.map((x) => {
    const last = x.points[x.points.length - 1];
    return rowWrap(h('button', { type: 'button', class: `row ${last.out ? 'lv1' : ''}`, 'data-ind': `blood:${x.code}`, 'data-tip': `b:${x.code}:${p.id}`, onclick: () => openDetail(`blood:${x.code}`) },
      h('b', { class: 'r-name' }, x.name),
      h('span', { class: `r-num ${x.units ? '' : 'nounit'} ${last.out ? 'lvc1' : ''}` }, fmtVal(last.v)),
      x.units ? h('span', { class: 'r-unit' }, x.units) : null,
      h('span', { class: 'r-time text' }, `Last test ${tpText(last.tp)}`),
      last.out ? h('span', { class: 'r-state lvc1' }, icon('info', { size: 14 }), 'Outside the lab range') : null,
      icon('chevron-right', { size: 18, cls: 'chev' })), `b:${x.code}:${p.id}`, x.name);
  });
  byId('groups').replaceChildren(h('section', { class: 'group' },
    h('div', { class: 'group-head' }, h('h2', {}, 'Blood tests before and after flight'), h('p', {}, 'Reference ranges come from the same NASA tables (lab ranges).')),
    h('div', { class: 'rows' }, ...rows)));
  byId('needs').hidden = true;
  byId('measures-sub').textContent = `${p.name}: real de-identified data from NASA OSDR (Inspiration4, 2021).`;
  applyFind();
}

// ---------- rendering: one measure, with a choice of period ----------
const PERIODS = [['7', '7 days', 'last 7 days'], ['30', '30 days', 'last 30 days'], ['flight', 'Whole flight', 'whole flight'], ['before', 'Before flight', 'before flight'], ['all', 'All', 'all readings'], ['custom', 'Custom', 'chosen dates']];

function periodRange(points) {
  const now = msOf(nowTime());
  if (ui.period === '7') return { from: now - 7 * DAY, to: now + DAY };
  if (ui.period === '30') return { from: now - 30 * DAY, to: now + DAY };
  if (ui.period === 'flight') return { from: msOf(MISSION.launch) - 2 * DAY, to: msOf(MISSION.landing) + 4 * DAY };
  if (ui.period === 'before') {
    const first = points.length ? Math.min(...points.map((p) => p.t)) : msOf(MISSION.launch) - 30 * DAY;
    return { from: Math.min(first, msOf(MISSION.launch) - 7 * DAY) - 3 * DAY, to: msOf(MISSION.launch) + 2 * DAY };
  }
  if (ui.period === 'custom' && ui.from && ui.to) {
    const from = new Date(`${ui.from}T00:00:00Z`).getTime();
    const to = new Date(`${ui.to}T23:59:59Z`).getTime();
    if (Number.isFinite(from) && Number.isFinite(to) && to > from) return { from, to };
  }
  return null;
}

function openDetail(indicator) {
  if (ui.screen !== 'detail') ui.backTo = ui.screen;
  if (!ui.periodChosen && window.innerWidth < 600) ui.period = '30';
  ui.detail = indicator;
  ui.screen = 'detail';
  render();
  window.scrollTo(0, 0);
}

const NORM_NAMES = { earthGeneral: 'General, Earth', spaceGeneral: 'General, space', personalEarth: 'Personal, Earth', personalSpace: 'Personal, space' };
const BACK_LABEL = { home: 'Today', measures: 'All measures', alerts: 'Messages', setup: 'Settings' };
const backButton = () => btn('secondary small back', BACK_LABEL[ui.backTo] || 'All measures', () => setScreen(ui.backTo || 'measures'), 'chevron-left');
const cornerTip = (key, label) => { const b = tipButton(key, label); b.classList.add('corner'); return b; };
const more = (title, ...children) => h('details', { class: 'more' }, h('summary', {}, icon('chevron-right', { size: 18 }), title), h('div', {}, ...children));

function periodBar(onChange) {
  return h('div', { class: 'periods' },
    h('div', { class: 'seg small', role: 'group', 'aria-label': 'Period' }, ...PERIODS.map(([key, label]) => h('button', {
      type: 'button', 'aria-pressed': String(ui.period === key), onclick: () => { ui.period = key; ui.periodChosen = true; onChange(); },
    }, ui.period === key ? icon('check', { size: 14 }) : null, label))),
    ui.period === 'custom' ? h('span', { class: 'custom' },
      h('label', {}, 'From (GMT)', h('input', { type: 'date', value: ui.from, onchange: (e) => { ui.from = e.target.value; onChange(); } })),
      h('label', {}, 'To (GMT)', h('input', { type: 'date', value: ui.to, onchange: (e) => { ui.to = e.target.value; onChange(); } }))) : null);
}

function renderDetail() {
  const host = byId('screen-detail');
  const p = personById[ui.person];
  if (String(ui.detail).startsWith('blood:')) return renderBloodDetail(host, p, ui.detail.slice(6));
  const indicator = ui.detail;
  const cell = cellBy[indicator];
  const owner = cell.section === 'env' ? SHIP : p;
  const series = seriesOf(owner.id, indicator);
  const allPoints = series.flatMap((s) => s.points);
  const range = periodRange(allPoints);
  const now = nowTime();
  const m = cell.kind === KIND.NUMBER ? measureState({ machine, person: owner, cell, mission: MISSION, now }) : null;
  const fc = m && m.forecast && m.forecast.line ? m.forecast : null;
  const showTrend = Boolean(fc) && (ui.period === 'flight' || ui.period === 'all');
  const lines = [];
  if (cell.normType === 'baseline-percent') { const b = bandOf(cell, owner); if (b) lines.push({ v: b.min, label: `Limit: ${cell.norm.minPercent}% of own pre-flight level` }); }
  if (indicator === 'radiation') lines.push({ v: cell.norm.max, label: 'NASA career limit' });
  if (indicator === 'bp') lines.push({ v: cell.norm.sysBelow, label: `Systolic: below ${cell.norm.sysBelow}` }, { v: cell.norm.diaBelow, label: `Diastolic: below ${cell.norm.diaBelow}` });

  const facts = [];
  const about = [];
  if (fc) {
    const what = indicator === 'bp' ? 'Systolic pressure' : 'This measure';
    const side = fc.crossing && fc.crossing.side === 'below' ? 'below' : 'above';
    const lastOut = m.last && m.last.status === STATUS.OUT;
    if (lastOut) facts.push(`The last reading (${stamp(m.last.time, now)}) is outside the normal range.`);
    else if (fc.crossing && fc.crossing.already) facts.push(`If the line through the flight readings holds, ${lower(what)} is already ${side} the normal range.`);
    else if (fc.crossing && fc.crossedBeforeNow) facts.push(`If the line through the flight readings holds, ${lower(what)} left the normal range around ${fmtDate(fc.crossing.date)}, after the last reading. A new reading is needed.`);
    else if (fc.crossing) facts.push(`${what} is going ${fc.crossing.side === 'below' ? 'down' : 'up'}: if this line holds, it goes ${side} the normal range around ${fmtDate(fc.crossing.date)}, before landing on ${fmtDate(MISSION.landing)}.`);
    else facts.push(`Steady within the normal range until landing on ${fmtDate(MISSION.landing)}, if this line holds.`);
    about.push("The forecast is a straight line through the in-flight readings (Claude's technical choice), not a validated medical model.");
  } else if (cell.kind === KIND.NUMBER) {
    facts.push(cell.onlyOnEarth ? 'Not measured in flight: only on Earth, before and after flight.' : 'To see where a measure is going, in-flight readings on at least three different days are needed.');
  } else {
    facts.push('Check-ins build up and are looked at in the planned review. By which rule the AI decides that spirits are falling is still the team\'s open question.');
  }
  if (EXPECTED[indicator]) facts.push(EXPECTED[indicator].text);
  if (indicator === 'strength') facts.push("In NASA studies muscle strength is measured before and after flight; NASA's 2023 evidence report says how it changes during flight is not well characterized.");
  if (ui.example && !owner.real) about.push('The example data are made up; the shapes of the changes come from published flight studies.');

  const normsBox = cell.norms ? h('dl', { class: 'norms' }, ...Object.entries(NORM_NAMES).map(([k, title]) => {
    const n = cell.norms[k];
    return h('div', { class: cell.compareWith === k ? 'used' : '' },
      h('dt', {}, title, cell.compareWith === k ? ' · compared with this one' : ''),
      h('dd', {}, n ? n.text : 'no data', n && n.src ? [' · ', h('a', { href: n.src.url, target: '_blank', rel: 'noopener' }, n.src.name)] : null));
  })) : h('p', {}, cell.normText || '');

  const a = assess({ machine, person: p, cells: CELLS, mission: MISSION, now });
  const lastEntry = machine.history(owner.id, indicator).slice(-1)[0] || null;
  const item = [...a.body.items, ...a.psyche.items].find((x) => x.cell && x.cell.indicator === indicator);
  const level = owner === SHIP ? (lastEntry && lastEntry.status === STATUS.OUT ? LEVEL.ATTENTION : LEVEL.FINE) : (item ? item.level : LEVEL.FINE);
  const norm = cell.kind === KIND.NUMBER ? normShort(cell, owner) : '';
  let verdict = 'No readings yet.';
  if (lastEntry) {
    if (lastEntry.status === STATUS.OUT) verdict = `${m && m.side === 'below' ? 'Below' : 'Above'} the normal range.`;
    else if (lastEntry.status === STATUS.OK) verdict = item && item.kind === 'forecast' ? `In the normal range now; the line leaves it around ${fmtDate(item.m.forecast.crossing.date)}.` : 'Within the normal range.';
    else verdict = cell.normType === 'record' ? 'Recorded: there is no checked norm for this measure.' : 'Recorded for the planned review.';
  }
  const alert = owner === SHIP ? null : alertsFor(p.id).find((x) => x.indicator === indicator);
  const raw = lastEntry ? valueText(indicator, lastEntry.value) : '';
  const shown = indicator === 'sleepQuality' && raw ? `${raw} of 7` : ORDINAL[indicator] ? cap(raw) : raw;
  const arrow = lastEntry && lastEntry.status === STATUS.OUT && m && m.side ? icon(m.side === 'below' ? 'arrow-down' : 'arrow-up', { size: 28, stroke: 2.4, cls: `lvc${level || 1}`, label: m.side === 'below' ? 'below the normal range' : 'above the normal range' }) : null;
  const periodName = (PERIODS.find(([k]) => k === ui.period) || PERIODS[2])[2];
  const chart = h('div', { class: 'chart', id: 'd-chart' });
  const tip = h('div', { class: 'tip', id: 'd-tip', hidden: true });
  const band = ORDINAL[indicator] ? null : bandOf(cell, owner);
  const shownPts = allPoints.filter((pt) => !range || (pt.t >= range.from && pt.t <= range.to));
  const how = [shownPts.length <= 40 ? 'Each dot is one reading.' : 'The line joins your readings.', band ? 'The shaded band is the normal range.' : null, shownPts.some((pt) => pt.out) ? 'Rings mark readings outside it.' : null].filter(Boolean).join(' ');

  fill(host, 
    backButton(),
    h('div', { class: 'detail-title' }, h('h1', {}, cell.label), owner === SHIP ? h('span', { class: 'chip neutral' }, 'Shared by the crew') : null),
    h('section', { class: `card now ${LV_CLASS[level]}` },
      cornerTip(`m:${indicator}:${owner.id}`, cell.label),
      lastEntry ? h('div', { class: 'now-value' }, h('b', {}, shown), cell.unit && cell.kind === KIND.NUMBER ? h('span', { class: 'u' }, cell.unit) : null, arrow) : null,
      h('div', { class: 'now-text' },
        h('p', { class: 'verdict' }, level ? h('span', { class: `lvc${level}` }, icon(LEVEL_ICON[level], { size: 18 }), ' ') : null, verdict, level ? h('span', { class: `lvc${level}` }, ` ${LEVEL_TITLE[level]}.`) : null),
        norm ? h('p', { class: 'meta' }, `Normal range: ${rangeText(cell, owner)}${cell.unit && cell.kind === KIND.NUMBER && cell.normType !== 'baseline-percent' ? ` ${cell.unit}` : ''}`) : null,
        lastEntry ? h('p', { class: 'meta' }, 'Last reading ', h('span', { class: 'mono' }, stamp(lastEntry.time, now))) : null)),
    alert ? h('div', { class: 'actions' }, btn('proc', 'What to do', () => openProcedure(alert), 'list-checks')) : null,
    periodBar(redrawDetail),
    h('section', { class: 'card chart-card' },
      cornerTip('t:chart', 'the chart'),
      h('h2', {}, `${cell.label}, ${periodName}`),
      h('p', { class: 'how' }, how),
      chart, tip,
      h('div', { class: 'legend', id: 'd-legend' }),
      showTrend ? h('p', { class: 'how' }, 'Forecast: a straight line through the flight readings, not a medical model.') : null),
    h('div', { class: 'prose' }, ...facts.map((x) => h('p', {}, x))),
    owner === SHIP ? null : cell.section === 'psyche' ? h('div', { class: 'actions' },
      aiButton('Start an anonymous session with AI', 'psyche', a),
      btn('secondary', 'Tell the doctor on Earth', () => openDoctor(a, 'psyche'), 'stethoscope', { 'data-tip': 't:tellDoctor' }),
      btn('secondary', 'Advice and articles', () => openAdvice(), 'list', { 'data-tip': 't:advice' })) : h('div', { class: 'actions' },
      aiButton('Analyse with AI', 'body', a),
      btn('secondary', 'Message the doctor', () => openDoctor(a, 'body', indicator), 'stethoscope', { 'data-tip': 't:doctor' })),
    h('div', {},
      more('About this measure',
        cell.effort ? h('p', {}, `Effort to measure: ${cell.effort}, on the team's scale of light, high and extreme.`) : null,
        ...about.map((x) => h('p', {}, x)),
        h('p', { class: 'muted' }, 'Which normal range it is compared with, and the sources:'),
        normsBox,
        owner === SHIP ? null : h('p', {}, h('button', { type: 'button', class: 'link', onclick: () => openArticles(indicator) }, 'Articles on this, to read without the AI'))),
      more('Show readings as a table', h('div', { class: 'table-wrap', id: 'd-table' })),
      cell.kind === KIND.NUMBER && !cell.onlyOnEarth && PLAUSIBLE[indicator] !== undefined || indicator === 'bp'
        ? more('Log a reading by hand', h('p', { class: 'note' }, 'Type a value from any device. It is saved as typed in by hand, with the time now.'), logReadingForm(cell, owner, () => redrawDetail()))
        : null),
  );
  const ord = ORDINAL[indicator] || null;
  drawHistory(chart, tip, {
    series, band, lines, mission: MISSION, fmt: fmtVal, ordinal: ord, outText: ord ? null : undefined, unit: cell.kind === KIND.NUMBER ? cell.unit : '',
    trend: showTrend ? { from: Math.max(fc.line.from, msOf(MISSION.launch)), at: fc.line.at } : null,
    label: `${cell.label}, ${owner === SHIP ? 'ship' : p.name}`, range,
  });
  drawTable(byId('d-table'), { series, fmt: fmtVal, ordinal: ord, outText: ord ? null : undefined, range });
  const legend = [];
  if (band) legend.push(h('span', {}, h('span', { class: 'band' }), 'Normal range'));
  if (showTrend) legend.push(h('span', {}, h('span', { class: 'trend-key' }), 'Forecast to landing'));
  if (shownPts.some((pt) => pt.out)) legend.push(h('span', {}, h('span', { class: 'out-key' }), ord ? cap(LOW[indicator]) : 'Outside the normal range'));
  byId('d-legend').replaceChildren(...legend);
  byId('d-legend').hidden = !legend.length;
}

// Redraw the measure page and keep the sections the person opened.
